#ifndef AIR_RUNTIME_OM2_RT_VAR_MANAGER_H_
#define AIR_RUNTIME_OM2_RT_VAR_MANAGER_H_

#include <cstdint>
#include <map>
#include <memory>
#include <mutex>
#include <set>
#include <string>
